case 'debuginteractive': {
    if (!isRegistered(m.sender)) {
        return Reply(global.mess.verifikasi)
    }
    if (checkLimit(m.sender, global.isPrem(m.sender), isCreator)) {
        return Reply(global.mess.limit)
    }

    alip.sendMessage(m.chat, {
        react: {
            text: '⏳',
            key: m.key
        }
    })

    try {
        const B = await import("@vanzxy/baileys")
        const I = B.WAProto.Message.InteractiveMessage

        const uuid = "debug-interactive-bloks-" + Date.now().toString(36)

        const a2ui = JSON.stringify({
            version: "v0.9",
            createSurface: {
                surfaceId: "welcome",
                root: "main_column",
                components: [{
                    id: "main_column",
                    component: "Column",
                    children: ["greeting", "cta_btn"]
                }, {
                    id: "greeting",
                    component: "Text",
                    text: "Welcome to A2UI!",
                    variant: "h2"
                }, {
                    id: "cta_btn",
                    component: "Button",
                    child: "cta_btn_text",
                    variant: "primary"
                }, {
                    id: "cta_btn_text",
                    component: "Text",
                    text: "Get Started"
                }]
            }
        })

        const interactive = I.create({
            header: I.Header.create({
                title: "Bloks Widget Debug",
                subtitle: "",
                hasMediaAttachment: false
            }),

            body: I.Body.create({
                text: "This is a test interactive message with bloksWidget"
            }),

            nativeFlowMessage: I.NativeFlowMessage.create({
                messageVersion: 1,
                buttons: [{
                    name: "cta_url",
                    buttonParamsJson: JSON.stringify({
                        display_text: "Book appointment",
                        url: "https://www.google.com"
                    })
                }]
            }),

            bloksWidget: I.BloksWidget.create({
                uuid,
                data: a2ui,
                type: "im_a2ui"
            })
        })

        const msg = await B.generateWAMessageFromContent(
            m.chat, {
                interactiveMessage: interactive
            }, {
                userJid: alip.user?.id
            }
        )

        await alip.relayMessage(
            m.chat,
            msg.message, {
                messageId: msg.key.id
            }
        )

        alip.sendMessage(m.chat, {
            react: {
                text: '✅',
                key: m.key
            }
        })
        addLimit(m.sender, global.isPrem(m.sender), isCreator)

    } catch (e) {
        console.error(e)
        Reply(`❌ Error: ${e.message}`)
        alip.sendMessage(m.chat, {
            react: {
                text: '❌',
                key: m.key
            }
        })
    }
}
